#!/usr/bin/env bash
# Renders every pass of the Star Lounge at its real size, one after another, each in its own
# DevGuard slot (heavy jobs take turns on this PC), then packs them and leaves out/.done.
#   lobby/tools/blender/all.sh [samples]
# Then, for the preview page: node preview/star-lounge/build.mjs assets && node preview/star-lounge/build.mjs
# It will not start a render with less than 5 GB of memory free.
# Do not edit this file while it runs: bash reads a script as it goes.
set -uo pipefail
here="$(cd "$(dirname "$0")" && pwd)"
samples="${1:-96}"
rm -f "$here/out/.done"
run() {
  local free
  free="$(free -m | awk '/^Mem:/ {print $7}')"
  if [ "$free" -lt 5000 ]; then echo "only $free MB free: not rendering $1"; exit 1; fi
  devguard slot -- "$here/run.sh" "$@" 2>&1 | grep -E "^saved|^packed|rror:|Traceback|File \"" | grep -v "Not freed"
}
run shell - "$samples"
run cards - "$samples"
run env - 64
for t in tex-planet tex-moon tex-sky; do run "$t"; done
for s in liner rocket saucer rock0 rock1 rock2; do run "sprite-$s" - 128; done
run pack
echo done > "$here/out/.done"
